#include "kmp_kmp.h"

static void CPF(char pattern[PATTERN_SIZE], int32_t kmpNext[PATTERN_SIZE]) {
    int q, l;
    int32_t k;
    kmpNext[0] = 0;
    k = 0;
    for (q = 1; q < PATTERN_SIZE; q++) {
        for (l = 0; l < PATTERN_SIZE; l++) {
            if (k == 0) break;
            if (pattern[q] == pattern[k]) break;
            k = kmpNext[k - 1];
        }
        if (pattern[q] == pattern[k]) {
            k = k + 1;
        }
        kmpNext[q] = k;
    }
}

int kmp(char pattern[PATTERN_SIZE], char input[STRING_SIZE], int32_t kmpNext[PATTERN_SIZE], int32_t n_matches[1]) {
    int i, l;
    int32_t j;
    CPF(pattern, kmpNext);

    n_matches[0] = 0;
    j = 0;
    for (i = 0; i < STRING_SIZE; i++) {
        for (l = 0; l < PATTERN_SIZE; l++) {
            if (j == 0) break;
            if (input[i] == pattern[j]) break;
            j = kmpNext[j - 1];
        }
        if (input[i] == pattern[j]) {
            j = j + 1;
        }
        if (j == PATTERN_SIZE) {
            n_matches[0] = n_matches[0] + 1;
            j = kmpNext[PATTERN_SIZE - 1];
        }
    }
    return n_matches[0];
}

